<script lang="ts">
 import { page } from '$app/state'; import { onMount } from 'svelte'; import PageHeader from '$lib/components/PageHeader.svelte'; import { listTasks, getSubtasks } from '$lib/api/tasks'; import type { TaskView } from '$lib/api/types';
 const projectKey=$derived(String(page.params.projectKey ?? '')); let roots=$state<TaskView[]>([]), children=$state<Record<string,TaskView[]>>({}), loading=$state(true), errorMessage=$state(''); onMount(async()=>{try{roots=(await listTasks(projectKey,1,100)).data.items.filter(t=>!t.parent_task_id); const entries=await Promise.all(roots.map(async root=>[root.id,(await getSubtasks(root.task_key)).data] as const));children=Object.fromEntries(entries)}catch(e){errorMessage=e instanceof Error?e.message:'子任务加载失败'}finally{loading=false}});
</script>
<PageHeader title="父任务与子任务" eyebrow="Subtasks" description="只展示任务 → 子任务两层，子任务不能继续拆分。" />
{#if errorMessage}<div class="workspace-card error-state">{errorMessage}</div>{/if}{#if loading}<section class="workspace-card state-box">正在加载任务层级…</section>{:else}<section class="workspace-card hierarchy">{#each roots as root}<article><header><a href={`/tasks/${root.task_key}`}><code>{root.task_key}</code><strong>{root.title}</strong></a><span>{children[root.id]?.length||0} 个子任务</span></header><div class="children">{#each children[root.id]||[] as child}<a href={`/tasks/${child.task_key}`}><code>{child.task_key}</code><span>{child.title}</span></a>{:else}<p>暂无子任务</p>{/each}</div></article>{:else}<p class="empty-inline">当前项目还没有父任务。</p>{/each}</section>{/if}
<style>.hierarchy{display:grid;gap:14px}.hierarchy article{border:1px solid var(--color-border);border-radius:12px;padding:16px}.hierarchy header{display:flex;justify-content:space-between;gap:12px}.hierarchy header a,.children a{display:flex;gap:10px;align-items:center}.hierarchy header span{color:var(--color-text-muted);font-size:12px}.hierarchy code{font-family:var(--font-mono);font-size:11px;color:var(--color-primary-strong)}.children{display:grid;gap:8px;margin-top:14px;padding-left:18px;border-left:2px solid var(--color-primary-soft)}.children a{padding:8px;background:#f8f9fc;border-radius:8px}.children p{margin:0;color:var(--color-text-muted);font-size:13px}.error-state{color:var(--color-danger);margin-bottom:16px}.state-box{text-align:center;color:var(--color-text-muted)}</style>
